def execute(arguments):
    """
    在目录中搜索文件

    参数:
        arguments (dict): 包含以下字段
            - path (str): 搜索的起始目录，必填
            - pattern (str): 文件名匹配模式，支持通配符，默认 "*"
            - recursive (bool): 是否递归搜索子目录，默认 True
            - max_results (int): 最大返回结果数，默认 100

    返回:
        dict: 包含搜索结果的字典
            - success (bool): 是否成功
            - path (str): 搜索目录
            - pattern (str): 匹配模式
            - matches (list): 匹配的文件路径列表
            - count (int): 匹配数量
            - error (str): 错误信息（失败时）
    """
    import os
    import fnmatch

    path = arguments.get("path", "")
    pattern = arguments.get("pattern", "*")
    recursive = arguments.get("recursive", True)
    max_results = arguments.get("max_results", 100)

    if not path:
        return {"success": False, "error": "请提供搜索目录"}

    if not os.path.exists(path):
        return {"success": False, "error": f"目录不存在: {path}"}

    try:
        matches = []

        if recursive:
            for root, dirs, files in os.walk(path):
                for name in files + dirs:
                    if fnmatch.fnmatch(name.lower(), pattern.lower()):
                        matches.append(os.path.join(root, name))
                        if len(matches) >= max_results:
                            break
                if len(matches) >= max_results:
                    break
        else:
            for name in os.listdir(path):
                if fnmatch.fnmatch(name.lower(), pattern.lower()):
                    matches.append(os.path.join(path, name))
                    if len(matches) >= max_results:
                        break

        return {
            "success": True,
            "path": path,
            "pattern": pattern,
            "matches": matches,
            "count": len(matches)
        }
    except Exception as e:
        return {"success": False, "error": str(e)}
